// Mesmo motivo do validador de hangares: mandar o evento inteiro como
// argumento de linha de comando estoura o limite do shell quando a Evolution
// embute thumbnail grande. Whitelist explícita, só com o que
// processar-fechamento.js usa.
const bruto = $input.first().json.body || $input.first().json;
const data = bruto.data || {};
const key = data.key || {};
const msg = data.message || {};
const img = msg.imageMessage || null;

const enxuto = {
  event: bruto.event,
  instance: bruto.instance,
  data: {
    key: {
      remoteJid: key.remoteJid,
      fromMe: key.fromMe,
      id: key.id,
      participant: key.participant,
      participantAlt: key.participantAlt,
    },
    pushName: data.pushName,
    message: {
      ...(img ? { imageMessage: { caption: img.caption || null, mimetype: img.mimetype || null } } : {}),
    },
  },
};

const payloadB64 = Buffer.from(JSON.stringify(enxuto)).toString('base64');

if (payloadB64.length > 60000) {
  throw new Error(`Payload enxuto ficou grande demais (${payloadB64.length} chars).`);
}

return [{ json: { payloadB64 } }];

// processar-fechamento.js imprime UM json em stdout com o resultado do fluxo
// inteiro e já enviou a resposta ao grupo (e ao admin, se aplicável) via
// --enviar. O n8n aqui só lê o resultado para responder o webhook.
const stdout = $input.item.json.stdout || '';
const linhas = stdout.trim().split('\n').filter(Boolean);
const ultimaLinha = linhas[linhas.length - 1];

if (!ultimaLinha) {
  return { json: { status: 'erro', mensagem: 'processar-fechamento.js não retornou nada em stdout.' } };
}

try {
  return { json: JSON.parse(ultimaLinha) };
} catch (err) {
  return { json: { status: 'erro', mensagem: `Saída não-json: ${ultimaLinha.slice(0, 300)}` } };
}
